def-struct(
    Algebra.IntegralDomain(R@Algebra.ctxt.ring, $+$@Algebra.ctxt.ring, $\cdot$@Algebra.ctxt.ring),
    struct(
        Algebra.UnitalRing(R@Algebra.ctxt.ring, $+$@Algebra.ctxt.ring, $\cdot$@Algebra.ctxt.ring),
        Algebra.CommRing(R@Algebra.ctxt.ring, $+$@Algebra.ctxt.ring, $\cdot$@Algebra.ctxt.ring),
        Logic.forall-typed(
            @a,
            R@Algebra.ctxt.ring,
            Logic.forall-typed(
                @b,
                R@Algebra.ctxt.ring,
                Logic.implies(Logic.and(Neq(a, Algebra.Zero(R@Algebra.ctxt.ring)), Neq(b, Algebra.Zero(R@Algebra.ctxt.ring))), Neq(Bop.apply($\cdot$@Algebra.ctxt.ring, a, b), Algebra.Zero(R@Algebra.ctxt.ring)))
            )
        )
    )
)
